  const fiscalSeason = parseNum(incomeRow["摮?"] || incomeRow.Season || balanceRow["摮?"] || balanceRow.Season);
  const annualizedParentNetIncome = Number.isFinite(parentNetIncome) && Number.isFinite(fiscalSeason) && fiscalSeason >= 1 && fiscalSeason <= 4
    ? parentNetIncome * (4 / fiscalSeason)
    : parentNetIncome;
  const parentComprehensiveIncome = parseNum(incomeRow["蝬???蝮賡?甇詨惇?潭??砍璆凋蜓"]);
  const parentOtherComprehensiveIncome = Number.isFinite(parentComprehensiveIncome) && Number.isFinite(parentNetIncome)
