function renderSparkline(points, accent = UI_COLORS.accent) {
  const nums = points.map((point) => point.value).filter(Number.isFinite);
  if (nums.length < 2) return `<div class="index-chart-empty">鞈?銝雲</div>`;
  const width = 260;
  const height = 72;
  const pad = 8;
  const min = Math.min(...nums);
  const max = Math.max(...nums);
  const span = max - min || 1;
  const coords = points.map((point, index) => {
    const x = pad + (index / Math.max(points.length - 1, 1)) * (width - pad * 2);
    const y = pad + (1 - (point.value - min) / span) * (height - pad * 2);
    return [x, y];
  });
  const line = coords.map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(" ");
  const area = `${pad},${height - pad} ${line} ${width - pad},${height - pad}`;
  return `
    <svg class="index-sparkline" viewBox="0 0 ${width} ${height}" role="img" aria-label="?韏啣??>
      <polyline points="${area}" fill="${accent}18"></polyline>
      <polyline points="${line}" fill="none" stroke="${accent}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"></polyline>
      ${coords.map(([x, y]) => `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="3" fill="${accent}"></circle>`).join("")}
    </svg>
  `;
}

function calcMarketTurnover(items = [], quotes = new Map()) {
  let validCount = 0;
  const total = (items || []).reduce((sum, stock) => {
    const quote = quotes?.get(`${stock.market}:${stock.code}`);
    const value = parseNum(quote?.value);
    if (!Number.isFinite(value)) return sum;
    validCount += 1;
    return sum + value;
  }, 0);
  return validCount ? total : null;
}

