function compactInstitutionalRows(rows = [], direction = "buy") {
  return [...rows]
    .filter((row) => Number.isFinite(parseNum(row?.netShares)))
    .sort((a, b) => direction === "buy" ? parseNum(b.netShares) - parseNum(a.netShares) : parseNum(a.netShares) - parseNum(b.netShares))
    .slice(0, 5);
}

function renderInstitutionalCanvasTable(rows = [], direction = "buy") {
  const body = compactInstitutionalRows(rows, direction).map((row, index) => `
    <tr>
      <td>${index + 1}</td>
      <td><a href="/stock/${encodeURIComponent(row.code)}">${htmlEscape(row.name || row.code)}</a></td>
      <td class="${direction === "buy" ? "up" : "down"}">${institutionalLots(row.netShares)}</td>
      <td>${renderMarketQuoteCell(row.close, 2)}</td>
    </tr>`).join("");
  return `<div class="institutional-canvas-table"><table><thead><tr><th>?活</th><th>?</th><th>鞎瑁都頞?/th><th>?嗥</th></tr></thead><tbody>${body || '<tr><td colspan="4" class="institutional-empty">?桀?瘝??舀?摨???/td></tr>'}</tbody></table></div>`;
}

