function institutionalChartPoints(history, key, width, height, padding, min, max) {
  const span = Math.max(1, max - min);
  return history.map((row, index) => {
    const value = parseNum(row?.[key]);
    if (!Number.isFinite(value)) return null;
    const x = padding + (history.length <= 1 ? 0 : index / (history.length - 1) * (width - padding * 2));
    const y = padding + (max - value) / span * (height - padding * 2);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).filter(Boolean).join(" ");
}

function renderInstitutionalFuturesChart(history = []) {
  const rows = history.filter((row) => Number.isFinite(parseNum(row?.day)));
  if (rows.length < 2) return '<div class="institutional-futures-empty" role="status">?漱??亦?芸像?風?脰???頞喉??思?蝜芾ˊ頞典??/div>';
  const values = rows.map((row) => parseNum(row.day));
  const changes = rows.map((row, index) => index ? parseNum(row.day) - parseNum(rows[index - 1].day) : 0);
  let min = Math.min(...values);
  let max = Math.max(...values);
  if (min === max) { min -= 1; max += 1; }
  const width = 620;
  const height = 190;
  const padding = 24;
  const dayPoints = institutionalChartPoints(rows, "day", width, height, padding, min, max);
  const step = (width - padding * 2) / (rows.length - 1);
  const barWidth = Math.max(3, Math.min(10, step * 0.58));
  const barBaseline = height * 0.58;
  const maxAbsChange = Math.max(...changes.map(Math.abs), 1);
  const bars = changes.map((change, index) => {
    const barHeight = Math.abs(change) / maxAbsChange * 54;
    const x = padding + index * step - barWidth / 2;
    const y = change >= 0 ? barBaseline - barHeight : barBaseline;
    const tone = change >= 0 ? "up" : "down";
    return `<rect class="institutional-chart-bar ${tone}" x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${barWidth.toFixed(1)}" height="${Math.max(barHeight, 0.8).toFixed(1)}"><title>${htmlEscape(rows[index].date)} 瘛券雿???${institutionalSigned(change, 0)} ??/title></rect>`;
  }).join("");
  const mid = rows[Math.floor((rows.length - 1) / 2)];
  return `<svg class="institutional-futures-chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="institutional-futures-chart-title">
    <title id="institutional-futures-chart-title">憭??唳???斗撟喳楊憿?瘥瘛券雿??? 30 ?亥粥??/title>
    <line class="institutional-chart-grid" x1="${padding}" y1="${padding}" x2="${width - padding}" y2="${padding}"></line>
    <line class="institutional-chart-grid" x1="${padding}" y1="${height - padding}" x2="${width - padding}" y2="${height - padding}"></line>
    <line class="institutional-chart-zero" x1="${padding}" y1="${barBaseline.toFixed(1)}" x2="${width - padding}" y2="${barBaseline.toFixed(1)}"></line>
    ${bars}
    <polyline class="institutional-chart-line oi" points="${dayPoints}"></polyline>
    <text x="${padding}" y="${height - 5}">${htmlEscape(rows[0].date.slice(5).replace("-", "/"))}</text>
    <text x="${width / 2}" y="${height - 5}" text-anchor="middle">${htmlEscape(mid.date.slice(5).replace("-", "/"))}</text>
    <text x="${width - padding}" y="${height - 5}" text-anchor="end">${htmlEscape(rows.at(-1).date.slice(5).replace("-", "/"))}</text>
  </svg>`;
}

