  const fallbackTotalData = { listed: split(totalRowsFor("listed")), otc: split(totalRowsFor("otc")) };
  const totalData = data.rankings?.total || fallbackTotalData;
  const rankSets = [totalData, data.rankings?.foreign || {}, data.rankings?.trust || {}];
  const warnings = (data.warnings || []).length
